target = '';\n   40 |     injectDaemon = true;\n   41 | \n   42 |     i = 1;\n   43 |     while i <= numel(varargin)\n   44 |         arg = strtrim(char(varargin{i}));\n   45 |         arg = regexprep(arg, '^[\"'']|[\"'']$', '');\n   46 |         argLower = lower(arg);\n   47 | \n   48 |         if any(strcmp(argLower, {'--wifi', '-w', 'wifi'}))\n   49 |             mode = 'wifi';\n   50 |             if i < numel(varargin) && ~startsWith(char(varargin{i+1}), '-')\n   51 |                 target = strtrim(char(varargin{i+1}));\n   52 |                 i = i + 1;\n   53 |             end\n   54 |         elseif any(strcmp(argLower, {'--usb', '-u', 'usb', 'serial'}))\n   55 |             mode = 'usb';\n   56 |             if i < numel(varargin) && ~startsWith(char(varargin{i+1}), '-')\n   57 |                 target = upper(strtrim(char(varargin{i+1})));\n   58 |                 i = i + 1;\n   59 |             end\n   60 |         elseif strcmp(argLower, '--raw')\n   61 |             injectDaemon = false;\n   62 |         elseif startsWith(upper(arg), 'COM') || startsWith(arg, '\/dev\/')\n   63 |             mode = 'usb';\n   64 |             target = upper(arg);\n   65 |         elseif ~isempty(regexp(arg, '^\\d+\\.\\d+\\.\\d+\\.\\d+$', 'once'))\n   66 |             mode = 'wifi';\n   67 |             target = arg;\n   68 |         end\n   69 |         i = i + 1;\n   70 |     end\n   71 | \n   72 |     if isempty(mode)\n   73 |         if strcmp(s.Mode, 'wifi')\n   74 |             mode = 'wifi';\n   75 |             target = s.Target;\n   76 |         elseif strcmp(s.Mode, 'serial')\n   77 |             mode = 'usb';\n   78 |             target = s.Target;\n   79 |         else\n   80 |             mode = 'wifi';\n   81 |             target = '192.168.4.1';\n   82 |         end\n   83 |     end\n   84 | \n   85 |     acli = find_arduino_cli();\n   86 | \n   87 |     if strcmp(mode, 'usb')\n   88 |         % Release any orphan serialport objects inside MATLAB before 