    if exist('serialportfind', 'file') || exist('serialportfind', 'builtin')\n  202 |             if isempty(targetPort)\n  203 |                 objs = serialportfind();\n  204 |             else\n  205 |                 objs = serialportfind('Port', upper(string(targetPort)));\n  206 |             end\n  207 |             for k = 1:numel(objs)\n  208 |                 try\n  209 |                     fprintf('[FLASH] Closing open MATLAB serial handle on %s...\\n', objs(k).Port);\n  210 |                     delete(objs(k));\n  211 |                 catch\n  212 |                 end\n  213 |             end\n  214 |         end\n  215 |     catch\n  216 |     end\n  217 | end\n  218 | \n  219 | function acli = find_arduino_cli()\n  220 |     [st, ~] = system('where arduino-cli >nul 2>&1');\n  221 |     if st == 0\n  222 |         acli = 'arduino-cli';\n  223 |         return;\n  224 |     end\n  225 |     defaultPath = 'C:\\Program Files\\Arduino CLI\\arduino-cli.exe';\n  226 |     if isfile(defaultPath)\n  227 |         acli = defaultPath;\n  228 |     else\n  229 |         error('ESP32:NoArduinoCLI', 'arduino-cli was not found. Please verify your installation.');\n  230 |     end\n  231 | end\n  232 | \n  233 | function usbPort = detect_usb_com_port(acli)\n  234 |     % 1. Check arduino-cli board list for explicitly marked USB serial ports\n  235 |     [~, out] = system(sprintf('\"%s\" board list 2>nul', acli));\n  236 |     lines = splitlines(string(strtrim(out)));\n  237 |     for k = 1:numel(lines)\n  238 |         if contains(lines(k), \"Serial Port (USB)\", \"IgnoreCase\", true)\n  239 |             tok = split(strtrim(lines(k)));\n  240 |             usbPort = char(tok(1));\n  241 |             fprintf('[FLASH] Auto-detected physical USB ESP32 port (via arduino-cli): %s\\n', usbPort);\n  242 |             return;\n  243 |         end\n  244 |     end\n  245 | \n  246 |     % 2. Query Windows PnP & Registry SERIALCOMM via PowerShell (line-by-line)\n  247 |     avail = serialportlist(\"available\");\n  248 |     allPorts = serialportlist(\"all\");\n  249 |     ignoredPorts = strings(0, 1);\n  250 |     usbCandidates = strings(0, 1);\n  251 | \n  252 |     if ispc\n  253 |         psCmd = [ ...\n  254 |             'powershell -NoProfile -Command \"' ...\n  255 |             'Get-CimInstance Win32_PnPEntity | Where-Object {$_.Name -match ''\\(COM\\d+\\)''} | ' ...\n  256 |             'ForEach-Object { Write-Output (''PNP|'' + $_.Name + ''|'' + $_.DeviceID) }; ' ...\n  257 |             '$reg = Get-ItemProperty ''HKLM:\\HARDWARE\\DEVICEMAP\\SERIALCOMM'' -ErrorAction SilentlyContinue; ' ...\n  258 |             'if ($reg) { $reg.PSObject.Properties | Where-Object {$_.Value -match ''^COM\\d+$''} | ' ...\n  259 |             'ForEach-Object { Write-Output (''REG|'' + $_.Name + ''|'' + $_.Value) } }\"' ...\n  260 |         ];\n  261 |         [st, psOut] = system(psCmd);\n  262 |         if st == 0 && ~isempty(strtrim(psOut))\n  263 |             pLines = splitlines(string(strtrim(psOut)));\n  264 |             for idx = 1:numel(pLines)\n  265 |                 ln = strtrim(pLines(idx));\n  266 |                 if startsWith(ln, \"PNP|\")\n  267 |                     tok = regexp(ln, '\\((COM\\d+)\\)', 'tokens', 'once');\n  268 |                     if isempty(tok), continue; end\n  269 |                     cPort = upper(string(tok{1}));\n  270 |                     if contains(ln, [\"BTHENUM\", \"Bluetooth\", \"Active Management Technology\", \"Intel(R) AMT\"], \"IgnoreCase\", true)\n  271 |                         ignoredPorts(end+1) = cPort; %#ok<AGROW>\n  272 |                     elseif contains(ln, [\"USB\", \"CP210\", \"CH340\", \"CH341\", \"CH910\", \"FTDI\", \"Silicon Labs\", \"UART\"], \"IgnoreCase\", true)\n  273 |                         usbCandidates(end+1) = cPort; %#ok<AGROW>\n  274 |                     end\n  275 |                 elseif startsWith(ln, \"REG|\")\n  276 |                     parts = split(